<?= $this->section('main-content') ?><main class="dashboard-container" aria-labelledby="delivery-providers-title"><div class="page-header d-flex justify-content-between align-items-center flex-wrap"><div><h1 id="delivery-providers-title">Delivery Providers</h1><p class="text-muted mb-0">Manage tracking providers used by Pharmacy deliveries.</p></div><button class="btn theme-btn" type="button" data-toggle="modal" data-target="#deliveryProviderModal" data-provider-reset="1">Add provider</button></div><section class="card mt-3"><div class="card-body"><form class="form-inline mb-3"><input class="form-control mr-2" name="search" value="<?= esc($search) ?>" placeholder="Search providers"><button class="btn btn-outline-dark mr-2">Search</button><a class="btn btn-light" href="<?= base_url('admin/delivery-providers') ?>">Clear</a></form><div class="table-responsive"><table class="table"><thead><tr><th>Provider</th><th>Tracking template</th><th>Support</th><th>Status</th><th>Sort</th><th>Actions</th></tr></thead><tbody><?php if (!$rows): ?><tr><td colspan="6" class="text-center text-muted py-5">No delivery providers found.</td></tr><?php else: foreach($rows as $row): ?><tr><td><strong><?= esc($row['provider_name']) ?></strong><small class="d-block text-muted"><?= esc($row['provider_code']) ?></small></td><td class="text-break"><?= esc($row['tracking_url_template']?:'Not configured') ?></td><td><?= esc($row['support_contact']?:'Not provided') ?></td><td><span class="badge badge-<?= (int)$row['status']===1?'success':'secondary' ?>"><?= (int)$row['status']===1?'Active':'Inactive' ?></span></td><td><?= (int)$row['sort_order'] ?></td><td class="text-nowrap"><button class="btn btn-sm btn-outline-dark js-provider-edit" type="button" data-provider='<?= esc(json_encode($row), 'attr') ?>'>Edit</button> <form class="d-inline js-provider-action" method="post" action="<?= base_url('admin/delivery-providers/toggle/'.(int)$row['id']) ?>"><?= csrf_field() ?><button class="btn btn-sm btn-light" type="submit"><?= (int)$row['status']===1?'Deactivate':'Activate' ?></button></form> <form class="d-inline js-provider-action" method="post" action="<?= base_url('admin/delivery-providers/delete/'.(int)$row['id']) ?>"><?= csrf_field() ?><button class="btn btn-sm btn-link text-danger" type="submit">Delete/archive</button></form></td></tr><?php endforeach; endif; ?></tbody></table></div><?= $pager?->links('delivery_providers') ?></div></section></main><div class="modal fade" id="deliveryProviderModal" tabindex="-1" role="dialog"><div class="modal-dialog modal-lg modal-dialog-scrollable"><div class="modal-content"><form id="deliveryProviderForm" method="post" action="<?= base_url('admin/delivery-providers/save') ?>"><?= csrf_field() ?><div class="modal-header"><h2 class="modal-title h5">Delivery Provider</h2><button type="button" class="close" data-dismiss="modal">&times;</button></div><div class="modal-body"><input type="hidden" name="id" id="providerId"><div class="form-row"><div class="form-group col-md-6"><label>Provider name</label><input class="form-control" name="provider_name" id="providerName"><div class="validation-error" id="provider_nameErr"></div></div><div class="form-group col-md-6"><label>Provider code</label><input class="form-control" name="provider_code" id="providerCode"><div class="validation-error" id="provider_codeErr"></div></div><div class="form-group col-md-8"><label>Default tracking URL template</label><input class="form-control" name="tracking_url_template" id="providerTemplate" placeholder="https://example.test/track/{tracking_reference}"><div class="validation-error" id="tracking_url_templateErr"></div></div><div class="form-group col-md-4"><label>Sort order</label><input class="form-control" type="number" min="0" name="sort_order" id="providerSort" value="0"></div><div class="form-group col-md-8"><label>Contact/support</label><input class="form-control" name="support_contact" id="providerSupport"></div><div class="form-group col-md-4"><label>Status</label><select class="form-control" name="status" id="providerStatus"><option value="1">Active</option><option value="0">Inactive</option></select></div></div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-dismiss="modal">Cancel</button><button class="btn theme-btn" type="submit">Save provider</button></div></form></div></div></div><?= $this->section('scripts') ?><script src="<?= base_url('assets/js/admin/delivery_provider.js?v=20261010.1') ?>"></script><?= $this->endSection() ?><?= $this->endSection() ?>
